class Solution {
public:
    string maxValue(string n, int x) {
        char cx = '0' + x;
        if (n[0] != '-') {
            for (int i = 0; i < n.size(); ++i) {
                if (n[i] < cx) {
                    return n.substr(0, i) + cx + n.substr(i);
                }
            }
            return n + cx;
        } else {
            for (int i = 1; i < n.size(); ++i) {
                if (n[i] > cx) {
                    return n.substr(0, i) + cx + n.substr(i);
                }
            }
            return n + cx;
        }
    }
};

class Solution {
    public String maxValue(String n, int x) {
        char cx = (char)('0' + x);
        if (n.charAt(0) != '-') {
            for (int i = 0; i < n.length(); ++i) {
                if (n.charAt(i) < cx) {
                    return n.substring(0, i) + cx + n.substring(i);
                }
            }
            return n + cx;
        } else {
            for (int i = 1; i < n.length(); ++i) {
                if (n.charAt(i) > cx) {
                    return n.substring(0, i) + cx + n.substring(i);
                }
            }
            return n + cx;
        }
    }
}

