var maxValue = function(n, x) {
    const sx = String(x);
    if (n[0] !== '-') {
        for (let i = 0; i < n.length; ++i) {
            if (Number(n[i]) < x) {
                return n.slice(0, i) + sx + n.slice(i);
            }
        }
        return n + sx;
    } else {
        for (let i = 1; i < n.length; ++i) {
            if (Number(n[i]) > x) {
                return n.slice(0, i) + sx + n.slice(i);
            }
        }
        return n + sx;
    }
};
